-- v0.21 recipe source lookup and staff source-first catalog.
create or replace function public.source_recipe_components(p_name text) returns jsonb language sql stable set search_path='public','pg_temp' as $$
with q as (select regexp_replace(lower(p_name),'[^0-9a-z가-힣]','','g') exact_key,regexp_replace(lower(regexp_replace(regexp_replace(p_name,'^[[:space:]]*1[lL][[:space:]]*','','i'),'[[:space:]]*1[lL][[:space:]]*$','','i')),'[^0-9a-z가-힣]','','g') base_key,p_name ~* '(^[[:space:]]*1[lL][[:space:]]*)|([[:space:]]*1[lL][[:space:]]*$)' is_1l), picked as (select c.* from public.recipe_source_components c,q where regexp_replace(lower(c.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key union all select c.* from public.recipe_source_components c,q where q.is_1l and regexp_replace(lower(c.menu_name),'[^0-9a-z가-힣]','','g')=q.base_key and c.variant_label ~* '1[[:space:]]*[lL]' and not exists(select 1 from public.recipe_source_components x where regexp_replace(lower(x.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key)) select coalesce(jsonb_agg(jsonb_build_object('item_id',null,'item_name',ingredient_name,'unit',unit,'quantity',quantity,'quantity_text',case when quantity is null then unit else null end,'variant_label',variant_label,'source_line',source_line) order by variant_label,line_order),'[]'::jsonb) from picked $$;
create or replace function public.source_recipe_instructions(p_name text) returns jsonb language sql stable set search_path='public','pg_temp' as $$
with q as (select regexp_replace(lower(p_name),'[^0-9a-z가-힣]','','g') exact_key,regexp_replace(lower(regexp_replace(regexp_replace(p_name,'^[[:space:]]*1[lL][[:space:]]*','','i'),'[[:space:]]*1[lL][[:space:]]*$','','i')),'[^0-9a-z가-힣]','','g') base_key,p_name ~* '(^[[:space:]]*1[lL][[:space:]]*)|([[:space:]]*1[lL][[:space:]]*$)' is_1l), picked as (select v.* from public.recipe_source_variants v,q where regexp_replace(lower(v.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key union all select v.* from public.recipe_source_variants v,q where q.is_1l and regexp_replace(lower(v.menu_name),'[^0-9a-z가-힣]','','g')=q.base_key and v.variant_label ~* '1[[:space:]]*[lL]' and not exists(select 1 from public.recipe_source_variants x where regexp_replace(lower(x.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key)) select coalesce(jsonb_agg(jsonb_build_object('label',variant_label,'content',content) order by sort_order),'[]'::jsonb) from picked $$;
create or replace function public.staff_recipe_list(p_employee_id bigint,p_pin text,p_store_id bigint)
returns table(product_id bigint,recipe_version_id bigint,menu_key text,menu_name text,category text,thumbnail_url text,instructions jsonb,components jsonb,assignment_status text,retirement_requested_at timestamptz)
language plpgsql security definer set search_path='public','extensions','pg_temp' as $$ declare v_last_type text; begin if not exists(select 1 from public.employees e where e.id=p_employee_id and e.store_id=p_store_id and e.is_active and e.pin_bcrypt=crypt(p_pin,e.pin_bcrypt)) then raise exception 'BAD_PIN'; end if; select ae.event_type into v_last_type from public.attendance_events ae where ae.employee_id=p_employee_id order by ae.id desc limit 1; if coalesce(v_last_type,'OUT')<>'IN' then raise exception 'NOT_CLOCKED_IN'; end if; return query with src as (select v.menu_name,min(v.category) category from public.recipe_source_variants v group by v.menu_name), base as (select hp.id product_id,hp.recipe_version_id,coalesce(hp.product_key,'source_'||md5(s.menu_name)) menu_key,s.menu_name,s.category,rv.thumbnail_url,public.source_recipe_instructions(s.menu_name) instructions,public.source_recipe_components(s.menu_name) components from src s left join lateral (select p.* from public.hq_products p where p.status='ACTIVE' and regexp_replace(lower(p.name),'[^0-9a-z가-힣]','','g')=regexp_replace(lower(s.menu_name),'[^0-9a-z가-힣]','','g') order by p.id limit 1) hp on true left join public.recipe_versions rv on rv.id=hp.recipe_version_id) select b.product_id,b.recipe_version_id,b.menu_key,coalesce(nullif(o.menu_name,''),b.menu_name),coalesce(nullif(o.category,''),b.category),coalesce(nullif(o.thumbnail_url,''),b.thumbnail_url),coalesce(o.instructions,b.instructions),case when o.store_id is null then b.components else o.components end,'ACTIVE'::text,null::timestamptz from base b left join public.store_recipe_overrides o on o.store_id=p_store_id and o.menu_key=b.menu_key order by coalesce(nullif(o.category,''),b.category),coalesce(nullif(o.menu_name,''),b.menu_name); end $$;